public double findMedianSortedArrays(int[] a, int[] b) {
    int m = a.length, n = b.length, total = m + n;
    int i = 0, j = 0;
    int prev = 0, curr = 0;
    for (int count = 0; count <= total / 2; count++) {
        prev = curr;
        if (i < m && (j >= n || a[i] <= b[j])) {
            curr = a[i++];
        } else {
            curr = b[j++];
        }
    }
    if (total % 2 == 1) {
        return curr;
    }
    return (prev + curr) / 2.0;
}

