def findMedianSortedArrays(self, a: list[int], b: list[int]) -> float:
    m, n = len(a), len(b)
    total = m + n
    i = j = 0
    prev = curr = 0
    for _ in range(total // 2 + 1):
        prev = curr
        if i < m and (j >= n or a[i] <= b[j]):
            curr = a[i]
            i += 1
        else:
            curr = b[j]
            j += 1
    if total % 2 == 1:
        return float(curr)
    return (prev + curr) / 2.0

